INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-001', 'Bogert-Berns Loop', 'Bogert Trail / Berns Trail Loop', TRUE, FALSE, 'Santa Rosa Mountains / South Palm Springs', 'Santa Rosa & San Jacinto Mountains National Monument', 'Bogert Trail Trailhead', '33.7890° N, 116.5214° W', 'Small dirt lot at trailhead. Arrive early morning to avoid limited spots. No fee.', 5.2, 975, 1522, '2.5 to 3 hours', '1.5 to 2 hours', 3, 'Hiking, Trail Running', 'Lollipop', 2, ARRAY['Jan','Feb','Mar','Nov','Dec']::TEXT[], ARRAY['Apr','May','Sep','Oct']::TEXT[], ARRAY['Jun','Jul','Aug']::TEXT[], 'Exposed with no shade. Start by 8am in shoulder season.', 'None. Bring minimum 2L per person.', TRUE, '12+', 'Yes — leash required', FALSE, TRUE, 'The Frank Bogert Trailhead sign is the first thing you see. Dark iron, silhouettes of horses and riders, the Santa Rosa Mountains rising behind it. The Desert Riders built these trails on horseback. You''re walking in their tracks. The canyon wash comes within the first quarter mile. Desert lavender in cooler months, the smell of the wash after rain, birdsong before the heat arrives. The world slows down here before the trail asks anything of you. Then it asks. The Bogert climb is steady and sustained, the trail rising through switchbacks with the city dropping away behind you. The views open gradually and then all at once. At the Bob Hope viewpoint, his residence sits perched on the hilltop directly across the canyon, closer than it should be, from an angle that exists nowhere else. The valley spreads behind it. Through the canyon gap below, the windmill farm is visible in the distance, Palm Springs framed between two ridgelines. The Berns Trail begins after the viewpoint. It descends from the ridgeline into a quiet valley, crosses the wash at the bottom, and climbs switchbacks up the far side to a small unmarked junction on the ridge above. The trail is unmarked throughout. Navigation requires attention. That''s part of what makes arriving back at the trailhead feel like something you genuinely earned.', 'The anonymity, first. Five miles from downtown Palm Springs and almost entirely solitary. The Frank Bogert Trailhead sign names the heritage but the trail delivers it. These switchbacks were cut by Desert Riders on horseback and they still feel that way. The canyon wash at the start has a sensory quality that''s hard to explain until you''re in it. The Bob Hope viewpoint is specific to a single moment on the climb and cannot be replicated from anywhere else. The Berns Trail descent is unmarked and requires a guide or offline navigation to complete. The trail gives you the full arc. You earn every part of it.', ARRAY['Solitude and quiet','Big Views']::TEXT[], NULL, 'https://ridewithgps.com/routes/56126082?privacy_code=rBGhjqMoRVS9jDcakbruiQDOMEp4Lgpg', NULL, NULL, NULL, NULL, 'Unmarked junctions on Berns section — guide or offline map required. No shade above canyon wash. Rocky descent on Berns switchbacks — caution for knee injuries.', '4 - Good', 'Retrace Bogert Trail to trailhead.   In emergencies, the below contact information should be used. Emergency: 911. Riverside County Search & Rescue: (951) 955-4930.', 'South Palm Springs', '12 min', FALSE, TRUE);
INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-002', 'Henderson-Garstin Loop', 'Henderson-Shannon-Garstin Loop', TRUE, FALSE, 'Santa Rosa Mountains / South Palm Springs', 'Santa Rosa & San Jacinto Mountains National Monument', 'Garstin Trail', NULL, 'Small cul-de-sac on Barona Rd. in the Indian Canyons neighborhood.  Street parkting fills up quickly on weekends.  No fee.', 3.5, 974, 1490, '1.5 - 2 hours', '40 mins to 1.5 hours', 3, 'Hiking, Trail Running', 'Loop', 3, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep']::TEXT[], ARRAY['Jun','Jul','Aug']::TEXT[], 'The Henderson Trail is shaded by the mountain on most mornings. All other sections are fully exposed the rest of the day. Start by 8am in shoulder season.', 'None. Bring minimum 2L per person.', TRUE, '12+', 'No', FALSE, TRUE, 'The Shannon Trail opens along the Palm Canyon Wash, undulating single track through a quiet gallery of desert life. Barrel cactus, cholla, beavertail. Birds in the brush. The desert unhurried and alive before the heat arrives. The Earl Henderson climb lifts you out of it. The trail narrows, the views open, and the shelf sections ask you to pay attention in a way that feels good rather than urgent. Then a switchback stops you entirely. Across the canyon, Bob Hope''s house sits at the top of its hill closer than it should be, from an angle that exists nowhere else in Palm Springs. Drop your eyes to the airport. A plane on final approach passes at eye level. You are standing in the middle of a city you thought you knew and seeing it for the first time. Higher still, the trail moves through boulder passages and narrow rock slots. Bighorn sheep move through these same sections. If you see one, it will be close. It will look directly at you. The Garstin Trail returns you to the valley with the morning behind you and the whole day still ahead.', 'Most visitors to Palm Springs never leave the valley floor. This loop puts you above it within the first mile and keeps you there. The Shannon Trail offers some of the best cactus variety in the area alongside a wash alive with birds and small desert wildlife. The Earl Henderson shelf sections carry genuine exposure without being punishing. The Bob Hope viewpoint exists at a single switchback on this trail and cannot be replicated from anywhere else. Bighorn sheep encounters on the upper sections are common enough to expect and rare enough to remember. The Garstin descent returns you to the trailhead having seen the city from a perspective that changes how it looks when you''re back in it.', ARRAY['Big Views','Interesting geology','Photography opportunities']::TEXT[], NULL, 'https://ridewithgps.com/routes/56126485?privacy_code=2aE2zBiqHFVzHT4UJ2zhYTCfGB09YrFP', NULL, NULL, NULL, NULL, 'Shelf trail sections carry real exposure, with steep drop-offs along the Earl Henderson climb. Bighorn sheep are commonly encountered in these same sections — move slowly and give them space. Outside of the shaded Shannon Trail opening, the rest of the loop is fully exposed to heat.', '4 - Good', 'Several bail options exist along this loop. From the Earl Henderson Trail, cut across the wash to exit early. From Cahuilla Peak, the Araby Trail offers a way down. Continuing forward on the Garstin Trail simply finishes the loop. The Palm Hills trailhead system is also reachable, though it''s the longest of the egress options. The Bogert Trail provides an additional exit as well.  In emergencies, the below contact information should be used. Emergency: 911. Riverside County Search & Rescue: (951) 955-4930.', 'South Palm Springs', '12 min', FALSE, TRUE);
