INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-008', 'Palm Hills Loop', 'Goat Trails', FALSE, FALSE, 'Santa Rosa Mountains / South Palm Springs', 'Palm Hills Park', 'Palm Hills', NULL, 'Dirt parking lot at the end of Palm Hills Rd off of S Highway 111.  Adjacent to the Vons grocery store.', 3, 720, 991, '1.5 - 2 hours', '.75 to 1 hour', 2, 'Hiking, Trail Running, Mountain Biking', 'Loop', 2, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep']::TEXT[], ARRAY['Jun','Jul','Aug']::TEXT[], 'Exposed with no shade. Start by 8am in shoulder season.  Start by 7am in summer.', 'None. Bring minimum 2L per person.', TRUE, '12+', 'No', TRUE, FALSE, 'The Palm Hills Trailhead sits on land that almost became something else entirely. This old quarry was saved from development and is now protected by the Oswit Land Trust. The quarry is mostly gone, with just occasional patches of machined rock betraying what happened here, and what remains is a quiet stretch of desert mountain terrain threaded by a dirt road that anchors the whole area and connects more trails than any first visit will reveal. The route today follows Desert Riders heritage trail through some of the best terrain in the system. The dirt road climbs through dark volcanic rock, trail markers confirming the way. The transition to single track is where the character sharpens. Murray Peak and San Jacinto appear ahead as the views open. Near the top, a large heart built from dark volcanic rocks faces out over the city. Then the trail drops left into the canyon. Fan palms grow from cracks in smooth pale granite, their roots reaching water that seeps through the stone year-round. Ferns grow from the rock face. A broad chute of water-carved granite angles down through the canyon. The trail passes directly through it. The Desert Riders named this place Jane''s Hoffbrau. In it, you feel genuinely transported. Somewhere secret, somewhere that asks nothing of you except to sit in it and pay attention. A major road is half a mile away. You would never know it. The climb out is the most demanding section. Steep, rocky, the trail threading through layers of volcanic and sedimentary stone. The canyon opens below and the palms appear from above, tucked impossibly into the cleft of the rock. A Desert Riders sign marks the junction above: Jane''s Hoffbrau behind you, Clara Burgess ahead, and the return to the trailhead up the hill to the right. The ridgeline returns you to wide views and the dirt road below.', 'Palm Hills Loop sits on land the Oswit Land Trust saved from quarry development, and the trails built through it by the Desert Riders pack more character into three miles than most trails twice the length. Murray Peak and San Jacinto frame the climb. A stone heart on the ridge faces the city. The trail descends into Jane''s Hoffbrau, a spring-fed palm oasis where water seeps from granite year-round, grows ferns from the rock face, and sustains fan palms rooted in water-carved stone. The experience inside it is genuinely transporting. The climb back out gives a second view of the same hidden canyon from above. Suitable for beginners and families, and interesting enough that no one will feel like they settled.', ARRAY['Solitude and quiet','Interesting geology','Photography opportunities']::TEXT[], NULL, 'https://ridewithgps.com/routes/56126904?privacy_code=yb0p8egVHXo370tFi7oF8jLvGIodpyiN', NULL, NULL, NULL, NULL, 'Many unmarked trails extend throughout Palm Hills. Follow the waypoints and landmarks to prevent getting lost.', '4 - Good', 'When in doubt, get back to the dirt road and head downhill.  Although several other trails lead off the mountains, the dirt road is the fastest and most consistent option.  Spot the airport or other key landmarks in order to maintain orientation.  In emergencies, the below contact information should be used. Emergency: 911. Riverside County Search & Rescue: (951) 955-4930.', 'South Palm Springs', '10 min', FALSE, TRUE);
