INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-015', 'Cathedral Canyon to Desert Riders Oasis', NULL, TRUE, FALSE, 'Santa Rosa Mountains / South Palm Springs', 'Santa Rosa & San Jacinto Mountains National Monument', 'Cathedral Canyon', NULL, 'Shared trailhead with the Cathedral Canyon Trail, but the two routes have nothing else in common. Parking is on a quiet residential street — be considerate of the neighborhood, don''t block driveways, and avoid parking directly in front of houses when you can help it.', 8.11, 2010, 2398, '4 - 5 hours', '2 - 2.5 hours', 4, 'Hiking, Trail Running', 'Out & Back', 4, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep']::TEXT[], ARRAY['Jun','Jul','Aug']::TEXT[], 'Exposed with no shade. Start by 7am in shoulder season.', 'None. Bring minimum 2L per person.', FALSE, '16+', 'No', FALSE, TRUE, 'The trailhead is on a quiet residential street. Park considerately, walk to the end of the road, and look for a line of palm trees and stumps on the left side of the dirt road. One stump has a small stack of rocks on top. That''s the marker. Everything about this trail begins as a secret. Cross the wash and the climb starts immediately. The trail rises along an exposed shelf cut into the canyon wall, the valley dropping away behind you as you gain elevation. Halfway up you stop and look back. Cathedral City sits small and distant below. The ridge you''ve already gained frames the view on both sides. The familiar world is still visible but it belongs to a different part of the day now. Then the hidden canyon appears. Not a place you descend into but a place you trace. The trail runs its edge, the canyon dropping away on one side, Cathedral City and the valley floor beyond it. It was invisible from the road. It was invisible from the wash. It reveals itself only to the people who climbed far enough to find it. On the ridgeline above, a large cairn sits alone with the entire Coachella Valley spread out behind it. Chest high, carefully stacked, built with real intention over many visits by someone you''ll never know. You stop here longer than you planned. The sandstone section follows. The trail carves through rounded granite slabs, smooth and fast underfoot, agave flanking both sides, San Jacinto appearing above the ridge ahead. The plateau opens beyond, wide and quiet, single track threading through open high desert with the mountains growing larger as you move toward them. The Desert Riders Oasis arrives without announcement. A wide sandy flat, a dozen picnic tables scattered across it, agave reaching skyward on every side, and the San Jacinto range filling the entire horizon. In the middle of it all, a bulldozer. Faded yellow, rusted tracks, completely intact, sitting exactly where it stopped working decades ago. Nobody brought it down. It never left. You sit down at one of the tables and look at the mountains and try to understand how a place like this exists eight miles from a resort hotel. Then you turn around. The descent runs the canyon rim back to the valley, the trail narrow and direct, the hidden canyon dropping away to one side and Cathedral City spread below on the other. On the way up you were too focused on climbing to take it all in. On the way down you see everything.', 'This trail has no official name and appears on no map. The trailhead is unmarked. The hidden canyon is invisible from the valley floor and from the road, revealing itself only after the climb. The trail runs its edge rather than descending into it, which means you carry the sense of it the entire way up and see it fully on the descent. A carefully built cairn marks a spot someone has clearly returned to many times. The sandstone section runs smooth and fast through carved granite with San Jacinto appearing above the ridge as you move through it. The turnaround at the Desert Riders Oasis delivers views and a sense of remoteness that most visitors to Palm Springs will never experience. The descent back along the canyon rim shows you everything the climb didn''t. The entire experience has the quality of being let in on something that exists entirely outside the version of the desert most people know.', ARRAY['Big Views','Solitude and quiet','Moving fast']::TEXT[], NULL, 'https://ridewithgps.com/routes/56127448?privacy_code=FZzfVsdyBvF6SmoecUr8SftRbLkzQaCL', NULL, 'https://connect.garmin.com/app/activity/22823847052', NULL, NULL, 'Unofficial, unmarked trail with no signage — navigation depends on landmarks and mile markers, not blazes. Remote and exposed once past the plateau, with long stretches offering no easy bail-out. Not a route for beginners or casual hikers.', '2 - Limited', 'Egress is limited. Dunn Road can be used to climb out to Highway 74 or descend back toward Cathedral Canyon via a separate trailhead. Alternatively, the Art Smith Trail descends from the Desert Riders Oasis to the base of Highway 74, just before the start of the ascent. Given limited egress options, this trail is recommended only for advanced hikers, athletes, and trail runners comfortable with self-supported backcountry travel.  In emergencies, the below contact information should be used. Emergency: 911. Riverside County Search & Rescue: (951) 955-4930.', 'Cathedral City', '20 minutes', FALSE, TRUE);
INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-016', 'North Lykken from Little Tuscany', NULL, TRUE, FALSE, 'San Jacinto / Downtown Palm Springs', NULL, 'North Lykken in Little Tuscany', NULL, 'The drive in is worth slowing down for — the road through Little Tuscany passes mid-century estates with historic designations and real architectural pedigree. The trailhead itself is barely marked, and the lot holds only a handful of cars. No street parking is available, so arrive early or have a backup plan.', 5.8, 1498, 1418, '3 - 4 hours', '1.5 - 2 hours', 3, 'Hiking, Trail Running', 'Out & Back', 4, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep']::TEXT[], ARRAY['Jun','Jul','Aug']::TEXT[], 'Exposed with no shade. Start by 7am in shoulder season.', 'None. Bring minimum 2L per person.', FALSE, '16+', 'No', FALSE, TRUE, 'The drive into Little Tuscany is the first sign you''re somewhere different. Mid-century estates with historic designations line the road in. The trailhead is barely marked. The lot holds a handful of cars. Most people in Palm Springs today have no idea this place exists. The opening climb is steep and quick on the heart rate, footing that asks you to be present from the first step. Then the trail tips over the other side and turns fast and flowing, switchbacks giving way to single track that moves with the terrain. Round a corner and the alluvial fan opens. Canyon walls rise on both sides and the mountain splits ahead like a gate. In winter and spring, grasses and wildflowers press in from every side, the desert alive and lush in a way that surprises almost everyone. In summer and fall, the vegetation pulls back and the landscape turns raw. Boulders in every direction, the rock faces exposed, the scale of the place impossible to miss. Cross the Tachevah Creek wash at the bottom and the trail begins to climb again. Halfway up, a switchback stops you. Directly below, the O''Donnell Golf Course sits impossibly green against the dry hillside. Las Palmas spreads to the left. Downtown Palm Springs beyond it, the valley stretching all the way to the Santa Rosa Mountains. You are standing on raw mountain trail looking straight down at a city that had no idea you were coming up here. The switchbacks continue to the top where the Skyline Trail intersects. Desert Riders picnic tables, a horse harness line, and a hidden pull-up bar for anyone who has something left. Then you turn around and do it all again in reverse, which on this trail feels like a different hike entirely.', 'North Lykken from Little Tuscany is the trail most Palm Springs visitors never find and most locals never think to recommend. The neighborhood approach is unlike any other trailhead in the area. The alluvial fan is the surprise the trail has been building toward: green, flowering, and lush in winter and spring, stark and dramatic in summer and fall, and completely wild in every season in a way that reframes what the desert is capable of. The O''Donnell viewpoint halfway up the final climb delivers one of the most dramatic city perspectives in the Coachella Valley. Bighorn sheep move through the upper sections. The turnaround at the Skyline intersection has picnic tables, a horse harness line, and a hidden pull-up bar. The trail gives you the full arc. You earn every part of it.', ARRAY['Big Views','Interesting geology','Solitude and quiet','Wildlife and nature']::TEXT[], NULL, 'https://ridewithgps.com/routes/56132100?privacy_code=QxXrfPqID6m0uZFahaFBxEudqz87xYrS', NULL, 'https://connect.garmin.com/app/activity/22095110018', NULL, NULL, 'Steep, scramble-like footing at the very start of the climb.  It''s not technical, but enough to demand attention and elevate the heart rate quickly. Later in the loop, a long shelf trail carries real exposure with steep drop-offs in places. The creek crossing at the bottom of the alluvial fan has a confusing run of small trail markers and sharp-angle turns that are easy to miss. The rock face on the return climb faces southeast and heats up quickly, even on early morning starts.  Heat exposure risk is real even on early morning starts. Bighorn sheep are commonly encountered on the shelf trail section; move slowly, don''t stare, and give them room to move on their own.', '3 - Fair', 'From most points on the trail, the simplest option is to bail back down toward the Little Tuscany neighborhood the way you came. From the loop at the top, two additional options open up: descend via the Museum Trail, or continue along the North Lykken Trail down to the Ramon trailhead.  In emergencies, the below contact information should be used. Emergency: 911. Riverside County Search & Rescue: (951) 955-4930.', 'North Palm Springs', '8 min', FALSE, TRUE);
