INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-022', 'South Lykken to Picnic Tables from Mesquite', NULL, TRUE, FALSE, 'Santa Jacinto Mountains / South Palm Springs', NULL, 'South Lykken at Mesquite', NULL, 'Street parking on Mesquite between South Palm Canyon and South Indian Canyon.  3/4 mile to the traihead.', 2.7, 916, 1498, '1:30 - 2 hours', '\<1 hour', 3, 'Hiking, Trail Running', 'Out & Back', 3, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep']::TEXT[], ARRAY['Jun','Jul','Aug']::TEXT[], 'Exposed with no shade. Start by 7am in shoulder season.  Start by 6am in summer.', 'None. Bring minimum 2L per person.', TRUE, '12+', NULL, TRUE, TRUE, 'The South Lykken trail starts where the city ends. Street parking is a three-quarter mile walk from the Mesquite trailhead, a quiet approach through the neighborhood edge that eases you into the mountain before the climbing starts. The trail switchbacks up exposed granite with the valley dropping away faster than feels reasonable, and a few sections ask you to use your hands on the rock, brief scrambles that require attention without demanding experience. In spring the trail is lush in a way that surprises people: dense grass in the drainage zones, beavertail blooming magenta, layered shadows moving across the Santa Rosas to the south. In summer, once the sun clears the ridge to the west, the trail runs mostly in shade and earns its reputation as a place where you can work hard without suffering for it.', 'There is a moment on the upper ridgeline where Tahquitz Falls appears with no warning. You come around a corner and it is simply there: a white thread dropping through dark rock into the shadowed canyon far below, the scale of it made stranger by the severity of the dropoff at your feet. Most people stop here without deciding to. Higher up, six or eight weathered picnic tables sit on an open saddle looking southeast toward Palm Canyon and the Santa Rosa Mountains. The birds are loud up here. The city is not. Bighorn sheep have a ledge on the upper climb where they gather most mornings, unbothered, the full valley arranged behind them. This trail is hard enough to earn, varied enough to stay interesting, and close enough to downtown that you can be back at the pool before noon.', ARRAY['Big Views','Wildlife and nature','Photography opportunities']::TEXT[], NULL, 'https://ridewithgps.com/routes/56132383?privacy_code=z2FINkwVJrMnH32dTiiTNCIZ6C7tBnmh', NULL, NULL, NULL, NULL, 'Some steep climbing with some shelf sections.  Steep dropoffs near the Tahquitz Falls Viewpoint.', '4 - Good', 'The fastest way is to return to the trailhead.  There are two other possible routes off of the mountain if South Lykken is followed further to the south after the picnic tables, but these options will take longer than returning to the trailhead and include several switchback sections and shelf trails.  In emergencies, the below contact information should be used. Emergency: 911. Riverside County Search & Rescue: (951) 955-4930.', 'Downtown Palm Springs', '5 min', FALSE, TRUE);
