INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-029', 'Oswit Canyon', NULL, FALSE, FALSE, 'Santa Jacinto Mountains / South Palm Springs', NULL, 'Oswit Canyon Trailhead', NULL, 'Plenty of street parking on South Palm Canyon Drive', 1.2, 166, 717, '1 - 1.5 hours', '20 mins', 1, 'Hiking, Trail Running', 'Loop', 1, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep','Jun','Jul','Aug']::TEXT[], NULL, 'Exposed with no shade. Start by 7am in shoulder season. Start by 6am in summer.', 'None. Bring minimum 2L per person.', TRUE, '4+', 'No', TRUE, FALSE, 'Oswit Canyon sits just south of the South Lykken trailhead, separated by a narrow wash, and is easy to walk past if you don''t know to look for it. The trail is a short loop through an alluvial fan preserved by the Oswit Land Trust, saved from development and left to do what desert land does: grow ocotillo and creosote and barrel cactus and buckhorn cholla in the lumpy, mineral-rich soil that water and wind have been shaping for centuries. The path is wide and sandy going up, more rocky coming back, and gentle enough in either direction that a small child can do the whole loop unassisted. Most people walk it in under an hour. Some take considerably longer, depending on how many rocks need to be examined along the way.', 'The plant life on this trail is as varied and dense as anywhere in the immediate area: encelia, desert lavender, cheesebush, beavertail, cholla, barrel cactus, and more, close enough to touch and low enough to see at any height. Near the far end of the loop, a large boulder sits above the trail with views back out of the canyon toward Palm Springs and the wind turbines in the distance. It is a good place to eat a snack and let the quiet settle. The trail is counterclockwise by preference, right fork first, gentle ascent before the rockier return. It is the kind of trail that teaches the desert to someone who has never met it, and returns something unhurried to everyone else.', ARRAY['Interesting geology','Moving slow and taking it all in','Solitude and quiet']::TEXT[], NULL, 'https://ridewithgps.com/routes/56144286?privacy_code=XpPFBXXS84mRrbm0qSCk8zUQmBrzGx7Z', NULL, NULL, NULL, NULL, 'Oswit Canyon Trail is very near to the South Lykken Trail.  Be mindful to start and stay on the Oswit Canyon Trail.', '4 - Good', 'Return to the trailhead via either direction on the loop.  In emergencies, the below contact information should be used. Emergency: 911. Riverside County Search & Rescue: (951) 955-4930.', 'South Palm Springs', '10 min', FALSE, TRUE);
