INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-031', 'Palms To Pines', NULL, FALSE, FALSE, 'San Jacinto / Downtown Palm Springs', 'Mount San Jacinto State Park', 'Art Museum Trail', NULL, 'PS Art Museum Parking Lot, Street Parking, or Downdown Parking Garage.  Typically plenty of parking available.', NULL, NULL, NULL, NULL, NULL, 5, 'Hiking, Trail Running', 'One Way', 5, ARRAY['Mar','Nov','Dec','Apr']::TEXT[], ARRAY['Jan','Feb','Oct']::TEXT[], ARRAY['Jun','Jul','Aug','May','Sep']::TEXT[], 'Exposed with no shade. Start by 5am in shoulder season.', 'None. Bring minimum 2L per person.', FALSE, '16+', 'No', FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE);
INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-032', 'Andreas Canyon', NULL, FALSE, TRUE, 'Indian Canyons / South Palm Springs', 'Indian Canyons', 'Andreas Canyon', NULL, 'Inside of Indian Canyons.  Park entry fee required.  Per person rates.  Dirt parking lot at the Andreas Canyon turnoff.', 0.9, 118, 1035, '45 mins', '10 mins', 1, 'Hiking, Trail Running', 'Loop', 1, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep','Jun','Jul','Aug']::TEXT[], NULL, 'Shaded with year nearly year-round stream.  Doable to about 105 degrees. Indian Canyons doesn''t open until 8am.', 'Reliable stream except in summer.  Starts to become stagnant during summer.', TRUE, '4+', 'No', TRUE, FALSE, 'Andreas Canyon is the shortest loop in the Indian Canyons system and one of the most concentrated. The trail sign at the trailhead says one mile. It does not say how long you will stay. The canyon side of the loop runs inside the gorge with the creek alongside and the walls close. The rock here is layered and angular, stacked in deep reds and burnt orange, with grass tufts growing from ledges high above. In the tightest sections the palm fronds brush the canyon wall on one side and the stream runs a few feet below on the other. The trail is sandy and easy underfoot. Birds move through the canopy. The sound of running water stays with you the entire way. The creek is accessible throughout the canyon half of the loop. About a fifth of a mile in, it broadens over large boulders into the calmest and largest of several pools, cold and clear over a pebble bottom. This is where shoes come off. Stone structures are visible on the hillside above, fenced off and silent. A small sign mentions the Andreas Canyon Club, a group that bought this land from the Southern Pacific Railroad in the early 1900s. Almost no other explanation is offered. The trail gives you just enough to wonder. The return runs the opposite side of the canyon, open and exposed, with the full palm grove and rock formations visible across the gorge. From up here the scale becomes clear: a dense stand of hundreds of palms pressed against towering red rock, the creek hidden below. The views open across the mountain ranges beyond. On a warm day this side earns the shade you left behind.', 'Andreas Canyon packs more into one mile than most trails manage in five. The canyon side is shaded, lush, and intimate, running alongside running water the entire way. The geology is dramatic in close quarters: layered canyon walls in deep red and orange rising steeply from the trail. Multiple pools are accessible along the creek; the largest and calmest sits about .2 miles in and is cold enough to matter on a warm afternoon. The return trail opens the whole picture, revealing the canyon from above and across. Two completely different experiences, one short loop. Plan for longer than the distance suggests.', ARRAY['Wildlife and nature','"Water - streams','pools','falls"','Learning about the place','Moving slow and taking it all in']::TEXT[], NULL, 'https://ridewithgps.com/routes/56144459?privacy_code=Zy0cTwsX7Mh9fDxWWRIvQMGPOxZifEQ4', NULL, NULL, NULL, NULL, 'Some shelf sections on the trail. Andreas Creek can swell and cover parts of the trail following heavy rains in the winter / spring.', '4 - Good', 'Return to the trailhead via either direction on the loop.  In emergencies, the below contact information should be used. Emergency: 911 Riverside County Search & Rescue: (951) 955-4930 Agua Caliente Tribal Ranger: 760.831.0045', 'Indian Canyons', '18 min', TRUE, FALSE);
INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-033', 'Murray Canyon Loop', NULL, FALSE, TRUE, 'Indian Canyons / South Palm Springs', 'Indian Canyons', 'Murray Canyon', NULL, 'Inside of Indian Canyons.  Park entry fee required.  Per person rates.  Dirt parking lot at the Murray Canyon turnoff.', 2.6, 441, 1108, '1.5 - 2 hrs', '0.5 - 1 hr', 2, 'Hiking, Trail Running', 'Loop', 3, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep']::TEXT[], ARRAY['Jun','Jul','Aug']::TEXT[], 'Exposed with little shade. Start by 8:30am in shoulder season.  Indian Canyons doesn''t open until 8am.', 'Reliable stream except in summer.  Starts to become stagnant during summer.', TRUE, '4+', 'No', TRUE, TRUE, 'Murray Canyon begins as a promise you can see before you earn it. From the fire road out of the parking lot, the palms are already visible ahead, rising from the wash in a dense green line against the mountain. Most trails make you guess at what''s coming. Murray Canyon shows you from the start. The trail follows the creek into the canyon, the path going soft and concave underfoot where decades of horse traffic have worn it into the earth. Watch for evidence of those horses. The palms thicken as the canyon walls close in, and the air cools. The trail moves in and out of tree cover, shaded under the palms, then open again beside them, but the canyon walls do the heavier work of keeping the morning cool. The stream crossings are real crossings, stone to stone over moving water, the kind that require a hand for small legs. Inside the canyon it is lush in a way that surprises people who think they know what the desert is. The return climbs the ridge above the canyon, and the trail becomes something entirely different. Below you, the palm grove threads through the canyon floor in a long green line. Ahead, the Coachella Valley opens wide, Palm Springs small and quiet in the distance, the Santa Rosa Mountains layered across the horizon. The finish is exposed and warms quickly. Start early.', 'Murray Canyon delivers more per mile than almost any trail in the Indian Canyons system: running water, canyon shade, a genuine palm oasis, boulder scrambles, and a ridge with sweeping valley views, all in under three miles. The canyon half is cool, intimate, and lush. The ridge half is open, exposed, and panoramic. They feel like two different trails joined by the same loop. Young children who hike regularly can do this. It will be near the edge of their abilities. That is the point. If you have the energy, continue up-canyon past the main oasis to Seven Falls. In winter and spring, it earns the name: multiple stream crossings, running waterfalls, a canyon that keeps going. In summer and fall the water slows, but the boulder scrambles remain and the desert wash character of the upper canyon is its own reward. Note that Seven Falls adds meaningful distance and effort. If you do it, save the ridge trail for another day or budget a rest before the climb back.', ARRAY['Wildlife and nature','"Water - streams','pools','falls"','Learning about the place','Moving slow and taking it all in']::TEXT[], NULL, 'https://ridewithgps.com/routes/56144735?privacy_code=wWELHBP6FSeqppAOcDMCTqxmq52Z2Y4V', NULL, NULL, NULL, NULL, 'Murray Canyon can be muddy following heavy rains in winter / spring.  The trail is also used by horseback riders.  Be mindful, calm, and step aside to let them pass.  Watch out for evidence of horses left on the trail.', '3 - Fair', 'Return to the trailhead via Murray Canyon trail or the Coffman trail.  Alternatively, head north out of Murray Canyon toward the Andreas Canyon parking lot.  In emergencies, the below contact information should be used. Emergency: 911 Riverside County Search & Rescue: (951) 955-4930 Agua Caliente Tribal Ranger: 760.831.0045', 'Indian Canyons', '18 min', TRUE, FALSE);
INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-034', 'Murray Canyon Out & Back', NULL, FALSE, TRUE, 'Indian Canyons / South Palm Springs', 'Indian Canyons', 'Murray Canyon', NULL, 'Inside of Indian Canyons.  Park entry fee required.  Per person rates.  Dirt parking lot at the Murray Canyon turnoff.', 2.6, 322, 979, '2 hrs', '.75 - 1 hr', 2, 'Hiking, Trail Running', 'Out & Back', 3, ARRAY['Jan','Feb','Mar','Nov','Dec','Apr','Oct']::TEXT[], ARRAY['May','Sep','Jun','Jul','Aug']::TEXT[], NULL, 'Exposed at the start and finish.  Mostly shaded under the palm tree canopy in the middle section of the route.  Will get warm in mid-day as there is little breeze.', 'Reliable stream except in summer.  Starts to become stagnant during summer.', TRUE, '4+', 'No', TRUE, FALSE, NULL, NULL, ARRAY['"Water - streams','pools','falls"','Photography opportunities','Wildlife and nature']::TEXT[], NULL, 'https://ridewithgps.com/routes/56730324?privacy_code=c8sT9tZHUBAY97tSAU1MeMq7P2lCpZfp', NULL, NULL, NULL, NULL, 'Murray Canyon can be muddy following heavy rains in winter / spring.  The trail is also used by horseback riders.  Be mindful, calm, and step aside to let them pass.  Watch out for evidence of horses left on the trail.', '4 - Good', 'Return to the trailhead.  Alternative route to the Andreas Canyon parking area if necessary.  In emergencies, the below contact information should be used. Emergency: 911. Riverside County Search & Rescue: (951) 955-4930. Agua Caliente Tribal Ranger: 760.831.0045', NULL, NULL, TRUE, FALSE);
